const raw = $input.first().json;
const body = raw.body || raw;

const event = String(body.event || '').toLowerCase().replace(/_/g, '.');
if (event === 'messages.set' || event === 'chats.set' || event === 'chats.upsert') {
  return [];
}
if (event && event !== 'messages.upsert') {
  return [];
}

const data = body.data || body;
const upsertType = String(data?.type || 'notify').toLowerCase();
if (upsertType === 'append') {
  return [];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.seen) staticData.seen = {};
const now = Date.now();
for (const [id, ts] of Object.entries(staticData.seen)) {
  if (now - ts > 5 * 60 * 1000) delete staticData.seen[id];
}

function extractText(msg) {
  if (!msg || typeof msg !== 'object') return '';
  if (msg.conversation) return String(msg.conversation);
  if (msg.extendedTextMessage?.text) return String(msg.extendedTextMessage.text);
  if (msg.imageMessage?.caption) return String(msg.imageMessage.caption);
  if (msg.videoMessage?.caption) return String(msg.videoMessage.caption);
  if (msg.buttonsResponseMessage?.selectedDisplayText) {
    return String(msg.buttonsResponseMessage.selectedDisplayText);
  }
  if (msg.listResponseMessage?.title) return String(msg.listResponseMessage.title);
  if (msg.ephemeralMessage?.message) return extractText(msg.ephemeralMessage.message);
  if (msg.viewOnceMessage?.message) return extractText(msg.viewOnceMessage.message);
  if (msg.documentWithCaptionMessage?.message) {
    return extractText(msg.documentWithCaptionMessage.message);
  }
  return '';
}

function processEntry(entry) {
  if (!entry?.key) return null;
  if (entry.key.fromMe === true) return null;

  const msgId = String(entry.key.id || '');
  if (msgId && staticData.seen[msgId]) return null;
  if (msgId) staticData.seen[msgId] = now;

  const jid = String(entry.key.remoteJid || '');
  if (!jid || jid.endsWith('@g.us') || jid === 'status@broadcast') return null;

  const phone = String(
    entry.key.remoteJidAlt ||
    entry.key.senderPn ||
    entry.key.participant ||
    jid
  )
    .replace('@s.whatsapp.net', '')
    .replace('@c.us', '')
    .split('@')[0]
    .replace(/\D/g, '');

  const text = extractText(entry.message).trim();
  if (phone && text) return { phone, text, messageId: msgId };
  return null;
}

let entries = [];
if (Array.isArray(data)) {
  entries = data;
} else if (Array.isArray(data?.messages)) {
  entries = data.messages;
} else if (data?.key) {
  entries = [data];
}

const out = [];
for (const entry of entries) {
  const row = processEntry(entry);
  if (row) out.push({ json: row });
}

return out;

const item = $input.first().json;
const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
if (!url || !key) throw new Error('Faltan SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY');
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: `${url}/rest/v1/rpc/fn_is_authorized`,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: { p_phone: item.phone },
  json: true,
});
// Sin respuesta a números no autorizados — silencio total
if (result !== true) return [];
return [{ json: item }];

const item = $input.first().json;
const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };
async function rpc(name, body = {}) {
  return await this.helpers.httpRequest({
    method: 'POST', url: `${url}/rest/v1/rpc/${name}`, headers, body, json: true,
  });
}
const [summaryRaw, salesRaw, stockRaw, lowStock] = await Promise.all([
  rpc.call(this, 'fn_business_summary'),
  rpc.call(this, 'fn_get_sales', { p_period: 'today' }),
  rpc.call(this, 'fn_get_stock'),
  this.helpers.httpRequest({
    method: 'GET',
    url: `${url}/rest/v1/vw_low_stock?select=name,stock_current,stock_minimum,status&limit=12`,
    headers: { apikey: key, Authorization: `Bearer ${key}` },
    json: true,
  }),
]);
const summary = Array.isArray(summaryRaw) ? (summaryRaw[0] || {}) : (summaryRaw || {});
const sales = Array.isArray(salesRaw) ? (salesRaw[0] || {}) : (salesRaw || {});
const stock = Array.isArray(stockRaw) ? stockRaw : [stockRaw];
return [{ json: {
  phone: item.phone, text: item.text, messageId: item.messageId,
  context: {
    resumen: summary,
    ventas_hoy: sales,
    inventario: stock.slice(0, 30),
    stock_critico: Array.isArray(lowStock) ? lowStock : [],
  },
}}];

const { phone, text, reply } = $input.first().json;
const url = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };
async function save(role, content) {
  await this.helpers.httpRequest({
    method: 'POST', url: `${url}/rest/v1/rpc/fn_save_conversation`, headers,
    body: { p_phone: phone, p_role: role, p_content: content }, json: true,
  });
}
await save.call(this, 'user', text);
await save.call(this, 'assistant', reply);
return [{ json: { phone, reply } }];

const { phone, reply } = $input.first().json;
const apiKey = $env.EVOLUTION_API_KEY;
const instance = $env.EVOLUTION_INSTANCE || 'comercio-ia';
await this.helpers.httpRequest({
  method: 'POST', url: `http://evolution-api:8080/message/sendText/${instance}`,
  headers: { apikey: apiKey, 'Content-Type': 'application/json' },
  body: { number: phone, text: reply }, json: true,
});
return [{ json: { phone, text: reply, sent: true } }];
